const crypto = require('crypto');

const input = $input.first().json ?? {};
const rawBody = input.raw_body ?? '';
const receivedHmac = input.hmac_header ?? null;
const secretName = input.secret_name || 'SHOPIFY_WEBHOOK_SECRET';
const secret = $vars[secretName] ?? null;

function safeCompareBase64(a, b) {
  if (!a || !b) return false;
  const aBuffer = Buffer.from(a, 'base64');
  const bBuffer = Buffer.from(b, 'base64');
  if (aBuffer.length !== bBuffer.length) return false;
  return crypto.timingSafeEqual(aBuffer, bBuffer);
}

let valid = false;
let reason = null;

if (!secret) {
  reason = 'missing_shopify_webhook_secret';
} else if (!receivedHmac) {
  reason = 'missing_shopify_hmac_header';
} else if (!rawBody) {
  reason = 'missing_raw_body';
} else {
  const calculatedHmac = crypto
    .createHmac('sha256', secret)
    .update(rawBody, 'utf8')
    .digest('base64');

  valid = safeCompareBase64(calculatedHmac, receivedHmac);
  if (!valid) reason = 'invalid_hmac';
}

return [{
  json: {
    valid,
    reason,
    validated_at: new Date().toISOString()
  }
}];

